"""One-off chapter refactor, preserving original deck/slide identifiers."""
from pathlib import Path
import re, html
root=Path(__file__).resolve().parents[2]
old=(root/'docs/reviews/ch37-ch38-ch39-baseline/ch37.html').read_text()
figures=re.findall(r'<figure class="deck">[\s\S]*?</figure>',old)
assert len(figures)==7
# Local diagram corrections; all frame order and accessibility IDs are retained.
figures[0]=figures[0].replace('x="420" y="357" class="tiny">reject: confirmation on lagging replica','x="250" y="355" class="tiny">confirm → Primary only')
figures[0]=figures[0].replace('x="570" y="144"','x="570" y="140"').replace('x="795" y="320"','x="795" y="316"')
figures[1]=figures[1].replace('DYNAMO-STYLE KV · preferred set {N1, N2, N3}','DYNAMO-STYLE KV · preferred {N1, N2, N3}; ACK assumed durable')
figures[1]=figures[1].replace('N1 and N2 acknowledge to KV Coordinator;','In this teaching scenario ACK means durable storage. N1 and N2 acknowledge to KV Coordinator;')
figures[1]=figures[1].replace('等 N1、N2 两个持久确认就能回 W=2，第三份仍可能在途。这次成功只覆盖单键。','本例约定 ACK 表示持久：等 N1、N2 两个确认回 W=2，第三份仍可能在途。W 本身不定义落盘。')
figures[1]=figures[1].replace('Two durable acknowledgments from N1 and N2 satisfy W=2 while the third copy may still be in flight. Success covers one key.','This example assumes durable ACKs: N1/N2 satisfy W=2 while the third copy may lag. W alone does not define durability.')
start=figures[3].index('aria-labelledby="d4s5t')
figures[3]=figures[3][:start]+figures[3][start:].replace('>PENDING session</text>','>COMMITTED</text>',1)
figures[3]=figures[3].replace('Metadata changes PENDING to COMMITTED with CAS.','Metadata changes PENDING to COMMITTED with CAS; its final label shows COMMITTED.')
figures[4]=figures[4].replace('x="755" y="180" class="tiny">80 × 20 B','x="690" y="202" class="tiny">80 × 20 B')
figures[5]=figures[5].replace('x="610" y="195" class="tiny">Bloom: no → skip; maybe → read','x="690" y="190" class="tiny">Bloom: no → skip; maybe → probe')
figures[6]=figures[6].replace('1,261,440,000 × 8 B ≈ 10.09 GB','All fragments: 1,261,440,000 × 8 B ≈ 10.09 GB')
figures[6]=figures[6].replace('Leaf 只扫金额条带；1,261,440,000×8 B≈10.09 GB。姓名、地址和 JSON 不在这条读取线上。','Leaf 只扫金额条带。10.09 GB 是所有片段的金额列总计，不是每片大小；本帧先示范 Leaf A。')
figures[6]=figures[6].replace('A leaf scans only amount: 1,261,440,000×8 B≈10.09 GB. Name, address and JSON stay outside this read path.','A leaf scans only amount. The 10.09 GB is the total across all fragments, not per fragment; this frame starts with Leaf A.')

def lang(z,e):return f'<span class="lang-zh">{z}</span><span class="lang-en">{e}</span>'
def h(n,z,e):return f'<h{n}>{lang(z,e)}</h{n}>'
def bi(z,e):return f'<div class="bilingual"><div class="lang-zh">{z}</div><div class="lang-en">{e}</div></div>'
def p(t):return f'<p>{t}</p>'
def sec(z,e,body,cls=''):return f'<section{(" class="+chr(34)+cls+chr(34)) if cls else ""}>{h(2,z,e)}{body}</section>\n'
def code(source,language,kind,region=None):
 s=(root/'examples/ch37'/source).read_text()
 if region:
  s=s.split(f'// BEGIN {region}\n',1)[1].split(f'    // END {region}',1)[0]
  s='\n'.join(line[4:] if line.startswith('    ') else line for line in s.splitlines())+'\n'
 ref=source+(f':{region}' if region else '')
 return f'<pre data-language="{language}" data-kind="{kind}" data-source="{ref}"><code>{html.escape(s,quote=False)}</code></pre>'
def details(z,e,body):return f'<details><summary>{lang(z,e)}</summary>{body}</details>'
def table(head,rows):return '<table><thead><tr>'+''.join('<th>'+lang(*v)+'</th>' for v in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+lang(*v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'

out=old[:old.index('  <section class="goal">')]
out+=sec('本章核心：先写查询，再选存储','Core: write the queries before choosing a store',bi(
 '<ul><li><strong>访问键与查询形状：</strong>点查、短范围、全文候选、大对象和全列扫描，需要不同的数据局部性。</li><li><strong>一次提交的不变量：</strong>订单、库存和幂等结果怎样同成败，不能靠两次 put 或先查后写代替。</li><li><strong>成功到底承诺什么：</strong>本地 WAL、远端持久、回放可见和灾难 RPO 分开；最后才比较引擎放大与运维成本。</li></ul>',
 '<ul><li><strong>Access key and query shape:</strong> point lookup, short range, term candidates, blobs and column scans need different locality.</li><li><strong>One-commit invariants:</strong> make order, stock and idempotency succeed together; two puts or a precheck cannot substitute.</li><li><strong>What success promises:</strong> separate local WAL, remote durability, replay visibility and disaster RPO before comparing engine amplification and operations.</li></ul>'),'goal')
assumptions=re.search(r'    <table><thead><tr><th><span class="lang-zh">假设（assumption）[\s\S]*?</table>',old).group(0)
assumptions=assumptions.replace('只匹配键形状，不证明安全与容量','持久 ACK 为本例约定；不证明安全与容量').replace('Key-shape match does not prove safety or capacity','Durable ACKs are assumed here; safety/capacity still unproved')
load=bi(p('<strong>主场景是结账。</strong>平均 40 笔/s，8 倍峰值 320 笔/s；每笔 1,500 B 订单快照，两个 40 B 索引。按 order_id 确认、按 user_id 列表，并按 sku 条件扣库存。选择事务型行存，是因为这些状态要同提交；320 不是单库够用的证明。')+p('先以一个主库、两份异步副本为待验证方案：一年快照和所列索引约 1.993 TB/份，三活副本加一紧凑备份约 7.97 TB；活副本旧版本按 1.5 倍计则约 10.96 TB。其他表、日志、空闲空间和备份历史另计。确认读回当前主库并开启新读视图；允许旧一秒的列表才考虑副本。'),p('<strong>The running workload is checkout.</strong> Assume 40 transactions/s on average, an 8× peak of 320/s, a 1,500 B snapshot and two 40 B index entries. Confirm by order_id, list by user_id, and decrement stock conditionally by sku. A transactional row store joins these changes in one commit; 320 alone proves no capacity limit.')+p('Evaluate one primary and two async replicas. Annual snapshots plus the specified indexes total about 1.993 TB/copy: three live copies and one compact backup need 7.97 TB, or 10.96 TB with a 1.5× live-version factor. Other tables, logs, free space and backup history are extra. Confirmation uses the current primary and a fresh read view; stale-allowed lists may use replicas.'))
load+=details('A1–A12：教学假设与决定','A1–A12: teaching assumptions and decisions',assumptions)
load+=details('复算容量、页写和热点','Recalculate capacity, page writes and the hot key',bi(
 p('40×86,400=3,456,000 笔/天；×365=1,261,440,000 笔/年。×1,500 B=1.89216 TB；×80 B 索引=0.1009152 TB；合计 1.9930752 TB。×4=7.9723008 TB；×(3×1.5+1)=10.9619136 TB。TB/MB 为十进制；8 KiB=8,192 B。')+p('峰值新增快照为 320×1,500=480,000 B/s=0.48 MB/s。A6 三个 8 KiB 脏页模型为 320×3×8,192=7,864,320 B/s≈7.86 MB/s，16.384 倍；漏 WAL、明细、库存、页分裂等，多次更新合页也会改变实际写量。它既非整事务盘写上界，也非示例库实际页数测量。')+p('20 次读/笔得到 800 QPS 平均、6,400 QPS 峰值。没有真实单机查询代价/幸存负载，就无法推出缓存或副本台数。热点 sku 为 320×30%=96 次/s；平均持锁 10 ms 时串行占用 96×0.010=0.96，须测排队与尾延迟。读副本不会分散这把写锁。'),
 p('40×86,400=3,456,000 orders/day; ×365=1,261,440,000/year. ×1,500 B gives 1.89216 TB; ×80 B adds 0.1009152 TB of indexes: total 1.9930752 TB. Four copies give 7.9723008 TB; ×(3×1.5+1) gives 10.9619136 TB. TB/MB are decimal; 8 KiB is 8,192 B.')+p('Peak new payload is 320×1,500=480,000 B/s=0.48 MB/s. A6 assumes three dirty 8 KiB pages: 320×3×8,192=7,864,320 B/s≈7.86 MB/s, or 16.384×. WAL, lines, stock and splits are omitted; coalescing also changes actual writes. This is neither a whole-transaction disk bound nor a page measurement of the example database.')+p('Twenty reads/order give 800 average and 6,400 peak QPS. Without measured query cost and survivor load, these do not determine cache or replica count. A 30% hot sku gets 96 updates/s; an assumed 10 ms mean lock hold gives 0.96 serial occupancy. Measure queueing and tail latency; read replicas do not spread this write lock.')))
load+=h(3,'用访问形状缩小候选，不从标签推能力','Use access shapes to shortlist candidates')
load+=table([('访问键 / 查询','Access key / query'),('本章候选','Candidate here'),('必须证明的边界','Required boundary')],[
 [('order_id；user_id 列表；sku 条件','order_id; user_id list; sku predicate'),('事务型行存；事务型 KV 也可评估','Transactional row store; transactional KV is also a candidate'),('订单/明细/库存/幂等同提交','Order/lines/stock/idempotency in one commit')],
 [('单键 get/put，可合并版本','Single-key get/put; mergeable versions'),('Dynamo 风格 KV','Dynamo-style KV'),('成员集合、版本合并、ACK 含义','Membership, version merge and ACK meaning')],
 [('会话/序列 + 有界时间范围','Conversation/series + bounded time range'),('复合索引或有序宽表','Composite index or sorted wide rows'),('键局部性；本例为单行原子','Key locality; this example has single-row atomicity')],
 [('许多行中少数字段的聚合','Aggregate a few fields across many rows'),('列条带分析路径','Column-striped analytical path'),('快照、完整片段和去重合计','Snapshot, complete fragments and deduplicated sum')],
 [('大块字节按 id 读','Large bytes by id'),('对象体 + 元数据','Object body + metadata'),('准确版本核验；元数据决定发布','Exact-version verification; metadata publication')],
 [('词 → 文档候选','Term → candidate documents'),('从权威源派生倒排','Inverted index derived from authority'),('outbox、版本/删除、查询回源','Outbox, version/delete and source validation')]])
load+=bi(p('数据模型、行/列布局、B+Tree/LSM 引擎和复制协议是不同轴。文档适合按聚合整体取用；图适合频繁沿关系展开；向量索引用于相似度检索，可有精确或近似路径。它们是否支持事务、条件写和过滤仍需逐项查能力，不能由 JSON、SQL 或 NoSQL 的外观下结论。'),p('Data model, row/column layout, B+Tree/LSM engine and replication protocol are separate axes. Documents suit aggregate retrieval; graphs suit frequent relationship traversal; vector indexes support similarity search with exact or approximate paths. Verify transactions, conditional writes and filtering separately instead of inferring them from JSON, SQL or NoSQL labels.'))
out+=sec('先定负载与访问路径','Fix the workload and access paths',load)

row=figures[0]+bi(p('<strong>图1：一个主库事务拥有订单、库存与结果。</strong>唯一键为可信 caller 的 <code>(caller,key)</code>，绑定完整规范请求；示例把重复 sku 合并、正数量有界验证并排序，delivery_ref 也参与绑定。同键同参读已存结果，同键换参冲突；外部支付不在这个事务内。'),p('<strong>Deck 1: one primary transaction owns order, stock and result.</strong> A trusted caller scopes the unique <code>(caller,key)</code>. Bind the whole canonical request, including delivery_ref; merge repeated skus, validate positive bounded quantities and sort. Same-key retries reuse the result; changed parameters conflict. External payment is outside this transaction.'))
row+=h(3,'关键实现：条件扣减与持久幂等','Implementation: conditional decrement and durable idempotency')
row+=bi(p('下面是伪代码；<a href="../examples/ch37/README.md">可执行适配</a>用 Python 标准库和 SQLite 3.38+，并实际运行同一条库存 SQL。<code>BEGIN IMMEDIATE</code>先获取该数据库的唯一写事务；这解释了为何幂等 SELECT 后不会有另一写者插队，不把“先查没有”当通用防重。其他引擎须处理唯一键冲突、行锁、死锁/序列化失败并有界重试整个事务。[11][12]'),p('This is pseudocode; the <a href="../examples/ch37/README.md">executable adapter</a> uses Python’s standard library and SQLite 3.38+ with the same stock SQL. <code>BEGIN IMMEDIATE</code> acquires the database’s single writer before reading idempotency, rather than relying on a generic not-found precheck. Other engines need unique-conflict handling, row locks and bounded whole-transaction retries for deadlock/serialization errors.[11][12]'))
row+=code('checkout.pseudo','Pseudocode','pseudocode')
row+=bi(p('<code>UPDATE ... on_hand&gt;=qty</code> 的受影响行数必须恰为 1。第二个 sku 不足时回到 savepoint，撤销前面的库存和订单，再提交稳定的 OUT_OF_STOCK 回执；补货后同键仍返回原拒绝，新业务意图才用新键。成功结果与库存同提交，不提交 PENDING；示例不清理幂等记录，真实保留期须覆盖重试/恢复窗口。'),p('Require exactly one affected row from <code>UPDATE ... on_hand&gt;=qty</code>. If the second sku fails, the savepoint undoes earlier decrements and the order, then the transaction stores a stable OUT_OF_STOCK receipt. Restocking does not change that key’s result; new intent uses a new key. Successful results and stock commit together; PENDING is never committed. The demo never expires dedupe records; real retention must cover retry/recovery windows.'))
row+=table([('轨迹','Trace'),('结果与恢复','Outcome and recovery')],[
 [('两客户端先各读最后 1 件，再写回 0','Two clients each pre-read the last item, then write 0'),('可各创建一单却只少 1 件；条件更新必须在事务内执行','Can create two orders after only one decrement; execute the predicate inside the transaction')],
 [('不同键并发抢最后一件','Different keys race for the last item'),('一个 CREATED；其他 OUT_OF_STOCK，不能负库存','One CREATED; others OUT_OF_STOCK; stock cannot become negative')],
 [('相同 caller/key 并发','Concurrent same caller/key'),('只提交一次效果，所有重试读同一回执','One effect; retries read the same receipt')],
 [('COMMIT 成功，201 丢失','COMMIT succeeds; 201 is lost'),('结果未知；保留同键查回执，不能换键重扣','Unknown to caller; recover by the same key instead of decrementing under a new key')],
 [('主库连接仍在旧快照','Primary connection retains an old snapshot'),('即使主库也看不到新单；确认必须开足够新的读视图','Even the primary can miss the order; confirmation needs a fresh-enough read view')]])
row+=h(3,'本地持久、复制和灾难 RPO','Local durability, replication and disaster RPO')
row+=bi(p('WAL 先满足所需持久屏障，数据页可稍后回刷；成功不要求逐笔刷完所有数据页。[7] 图中只等本地持久，复制异步：主盘永久损坏可同时丢订单与幂等表，重试不能补回未复制的事务，必须对账。提交前确知未提交则回滚；跨提交点断连则查同键，不能武断宣布失败。'),p('The required durable WAL barrier precedes persistent data-page flush; commit need not flush every data page.[7] This diagram waits only for local durability and replicates asynchronously. Permanent primary-disk loss can lose both orders and dedupe records; retries cannot reconstruct an unreplicated transaction. Reconcile business effects. A known pre-commit abort rolls back; a disconnect across commit is unknown until same-key recovery.'))
row+=bi(p('若承诺已确认写幸存单机故障，要等位于相应故障域的同步持久副本，并隔离旧主、只提升满足屏障的副本；这仍不涵盖所有地域同时丢失。[8] 收到、写入 OS、持久落盘和回放可见不同；PostgreSQL18 的 <code>remote_apply</code>等待同步副本回放，但旧快照仍需结束。列表一秒是目标，异步复制不自动兑现；没有可信回放/变更水位就不能证明最大陈旧，超限应回主或明确失败。'),p('To survive a host loss without losing acknowledged writes, wait for durable synchronous copies in the required failure domains, fence the old primary and promote only an eligible replica. This does not cover loss of every region.[8] Received, OS-written, durable and replay-visible are distinct. PostgreSQL18 <code>remote_apply</code> waits for synchronous replay, but readers must still leave old snapshots. A one-second list target is not automatic with async replication: without trusted replay/change watermarks, maximum staleness is unproved; route over-budget reads to the primary or fail explicitly.'))
out+=sec('行存：把不变量放进一次提交','Row store: put invariants in one commit',row)

kv=figures[1]+bi(p('<strong>图2限定为 Dynamo 风格单键协议。</strong>健康时 N=3、R=W=2：写确认 W={N1,N2}，后读 R={N2,N3} 在 N2 相交，但仍需版本排序/合并。反例换一轮写：N2 对写方失联、N3 投递延迟，候补 N4 代收，W={N1,N4} 已成功；N2 恢复但提示/N3 写尚未到时，R={N2,N3} 两份都可旧。2+2&gt;3 没有约束扩大后的成员集合。[2]'),p('<strong>Deck 2 is a Dynamo-style one-key protocol.</strong> With N=3 and R=W=2, healthy W={N1,N2} intersects later R={N2,N3}, but still needs version ordering/reconciliation. In a new write, N2 is unreachable, N3 delivery lags, and fallback N4 accepts W={N1,N4}. After N2 recovers but before handoff or N3 delivery, R={N2,N3} can return two old values. The inequality 2+2&gt;3 does not constrain the expanded membership.[2]'))
kv+=bi(p('图上 ACK 为“已持久”是额外教学约定。Dynamo 论文 §6.1 还讨论缓冲写、以耐久换延迟，不能由 W=2 推出两份已落盘。[2] hint 是修复，不是强读证明；严格 quorum 拒绝候补换成员会减少可写窗口，相交也不自动带来线性一致或跨键事务。'),p('Durable ACKs are an additional assumption in the diagram. Dynamo §6.1 also describes write buffering that trades durability for latency: W=2 alone does not prove two durable copies.[2] Hints repair placement; they do not prove strong reads. Refusing fallback membership reduces write availability, while intersection still does not create linearizability or a cross-key transaction.'))
kv+=bi(p('候选负载是可合并偏好或定义过增删合并规则的购物车。A9 的 1 KB 会话、6,400 QPS 只匹配键形状；撤销、一次性令牌和权限收紧不能随便读旧。LWW 覆盖会丢并发增量，不能安全扣库存；事务型 KV 是否满足结账，应另查提交和读契约，不能套这张图。'),p('Candidates include mergeable preferences or carts with defined add/delete reconciliation. A9’s 1 KB sessions at 6,400 QPS match a key shape without proving revocation, one-time-token or authorization safety. LWW can lose increments and cannot safely decrement stock. A transactional KV needs its own commit/read contract rather than inheriting this diagram.'))
out+=sec('单键 KV：写全成员集合与 ACK 含义','Single-key KV: name membership and ACK meaning',kv)

wide=figures[2]+bi(p('<strong>图3的局部性在行键。</strong>Bigtable2006 论文用 (row,column,timestamp)→bytes，tablet 管连续行范围，提供单行原子读写/读改写，不提供通用跨行事务。[1] 本例行键是 conversation_id+日桶，msg 限定符为 (sent_at,message_id)；50 条消息是 50 个单元格，同一单元格版本留给编辑。多页、多桶不自动组成一份快照，游标应固定查询边界及最后时间/id。'),p('<strong>Deck 3 localizes by row key.</strong> Bigtable’s 2006 paper models (row,column,timestamp)→bytes, assigns contiguous row ranges to tablets, and provides single-row atomic reads/writes/read-modify-writes without general cross-row transactions.[1] Here conversation_id plus a day bucket names the row; msg qualifiers use (sent_at,message_id). Fifty messages are fifty cells, while versions represent edits. Multiple pages/buckets need an explicit query boundary and time/id cursor rather than an assumed global snapshot.'))
wide+=bi(p('A8：2,000×400 B=0.8 MB/s；最近 50 条正文为 20 KB。规模小时，行存复合索引 (conversation_id,sent_at,message_id) 同样匹配“会话等值 + 时间范围/排序”；先测计划和工作集，再决定是否宽表。[14] 时间桶限制历史体积，不能分散同一当前热桶；加盐分散写后，读要 fan-out 并按时间/id 归并。全局时间前缀还会集中最新写。'),p('A8 gives 2,000×400 B=0.8 MB/s; fifty bodies total 20 KB. At smaller scale, a relational composite index (conversation_id,sent_at,message_id) fits conversation equality followed by time range/order. Inspect the plan and working set before choosing wide rows.[14] Time buckets bound history rather than spreading current hot writes. Salting adds fan-out and time/id merge; a global-time prefix concentrates fresh writes.'))
wide+=bi(p('节点内仍需合并内存与文件版本；过期数据停止可见和旧文件物理回收分开。宽表的列是行内限定符；分析列存把许多行上的同字段聚在一起。两者都能“扫描”，但短会话范围与全年金额 SUM 的读取代价不同。'),p('A node still reconciles memory/file versions; expiry visibility and physical file reclamation are separate. A wide-row column is a qualifier within a row, while an analytical stripe groups one field across rows. Both can scan, but a short conversation range and an annual amount SUM have different access costs.'))
out+=sec('宽表：按行键聚集短范围','Wide rows: cluster a short range by row key',wide)

obj=figures[3]+bi(p('<strong>图4把大字节直传和发布决定分开。</strong>先持久创建 PENDING 会话，绑定 caller/key、完整内容、blob_id、大小、校验和与期限，再签发准确键的 create-only 上传权限。S3 的 <code>If-None-Match: *</code>检查当前键版本是否存在；它不是对象天生不可变的证明。禁止绕过条件写、限制删除/重用键或绑定 version_id，才守住本例不可变身份。[10]'),p('<strong>Deck 4 separates direct bytes from publication.</strong> Persist a PENDING session binding caller/key, full content, blob_id, size, checksum and expiry, then issue create-only upload authority for that exact key. S3 <code>If-None-Match: *</code> checks the current key version; it does not make every object inherently immutable. Enforce conditions and restrict deletion/key reuse, or bind a version_id, to preserve the immutable identity assumed here.[10]'))
obj+=bi(p('PUT 超时是结果未知，先查上传结果并核验；存在不等于内容正确。可信验证器按该会话的完整 object_key（含存储命名空间）做 HEAD，proof 绑定 caller/upload_id/object_key/version/size/checksum。适配先拒绝错 caller/id，SQL 再核会话已存 key；同内容 B 的 HEAD 不能用于发布 A。客户端不能构造 proof，ETag 也不能一概当内容摘要。真实核验是外部契约，本地适配不实现 S3。[10]'),p('A PUT timeout is unknown: query and verify, not merely check existence. A trusted verifier HEADs the session’s full object_key, including its storage namespace, and binds proof to caller/upload_id/object_key/version/size/checksum. The adapter rejects wrong caller/id and SQL checks the stored key; B’s identical content cannot supply A’s publication proof. Clients cannot mint proof, and ETags are not universal content digests. Live verification remains external; the adapter does not implement S3.[10]'))
obj+=h(3,'关键实现：只有状态转换胜者有权发布或清扫','Implementation: only the transition winner may publish or clean')
obj+=code('publication.sql','SQL · CAS','teaching')
obj+=bi(p('SQLite 3.38+ 的 <code>unixepoch()</code>在拿到写事务后随语句采样，不复用锁前时间。先取完 RETURNING 行，再确认 COMMIT；0 行不代表获权。[12] 发布重试只在会话、完整对象键、准确版本/大小/校验和与已提交记录全相同时返回原 COMMITTED；清扫重试不给新的删除权。'),p('SQLite 3.38+ samples <code>unixepoch()</code> in the statement after acquiring the writer transaction rather than reusing pre-lock time. Consume RETURNING rows and confirm COMMIT before acting; zero rows grant no ownership.[12] Publication retries reuse COMMITTED only when session, full object key and exact version/size/checksum match. Cleanup retries grant no new deletion ownership.'))
obj+=bi(p('清扫若先把 PENDING 改成 ABORTED，迟到 finalize 失败；发布先赢则清扫不能删 COMMITTED。已签发请求仍可能在过期后落盘，清扫还需在权限失效、在途请求有界排空后复查准确版本的迟到孤儿。元数据必须 COMMITTED 才签发读权限；对象库与元数据库仍有两个提交。小而频繁变化、要同库存提交的订单行不会因字节量小就适合对象。'),p('If cleanup wins PENDING→ABORTED, late finalize fails; if publication wins, cleanup cannot delete COMMITTED. Previously issued uploads may finish after expiry, requiring exact-version orphan rechecks after authority expiry and a bounded in-flight drain. Issue read authority only for COMMITTED metadata. Body and metadata still have two commits; small mutable order rows needing stock atomicity do not fit this path merely because bandwidth is low.'))
out+=sec('对象：直传字节，条件发布元数据','Objects: direct bytes, conditional metadata publication',obj)

search=figures[4]+bi(p('<strong>图5的倒排是派生视图，源库是权威。</strong>正文、所有者、源版本和 outbox 同库事务，saved 不代表已可搜索。Relay 至少一次投递固定版本快照或删除标记；Indexer 按 doc_id/source_version 幂等，只在索引确认后推进交付，旧版本不能盖回新值/墓碑。中途宕机重投；单调源版本、删除保留与重建截止点要一起定义，详见 <a href="ch13.html">Ch13</a>。'),p('<strong>Deck 5 treats the inverted index as a derived view and the source as authority.</strong> Commit body, owner, source version and outbox together; saved does not imply searchable. Relay delivers versioned snapshots/deletions at least once. Indexer applies doc_id/source_version idempotently and advances only after index acknowledgment; old versions cannot overwrite new data/tombstones. Recovery replays; version order, deletion retention and rebuild cutoffs belong together. See <a href="ch13.html">Ch13</a>.'))
search+=bi(p('A10：80×20 B=1,600 B≈1.6 KB posting/文档，词典、位置、删除和副本另计。A4 的五秒是新鲜度目标，积压时看最老待办年龄。查询先拿候选 id/version，再回源校验当前 ACL、删除、版本和词匹配；可过滤陈旧命中，不能找回尚未入索引的新文档。源库/倒排缺失就有界失败，不能把不完整说成完整。'),p('A10 assumes 80×20 B=1,600 B≈1.6 KB of postings/document, excluding dictionary, positions, deletions and replicas. A4’s five seconds is a freshness target; monitor oldest pending age. Retrieve candidate ids/versions, then validate current source ACL, deletion, version and term match. This removes stale hits without discovering unindexed new documents. Bound failures or incomplete results when source/index data is unavailable.'))
search+=bi(p('若保存与可搜索必须同成败，可评估同事务引擎的全文索引。同步调用外部搜索仍是两次写，不会回滚已提交源数据。本章由源可重建，索引不能冒充唯一账本；若另选搜索引擎作权威，必须重新证明其耐久、更新、权限、备份/重建契约，而不是由“能存正文”推断。'),p('If saving and searchability must succeed together, evaluate full-text indexing in the same transaction engine. A synchronous external search call is still a second write and cannot undo the source commit. Here the source supports rebuilding, so the derived index cannot become the sole ledger. Choosing a search engine as authority requires a separate durability/update/authorization/backup/rebuild contract rather than inferring authority from stored display fields.'))
out+=sec('倒排：先保留源，再派生搜索','Inverted index: retain the source before deriving search',search)

engine=figures[5]+bi(p('<strong>图6上下是同一 API 的两种候选，不是串联两套库。</strong>B+Tree 按页组织有序键，点查沿树、范围读沿叶序；上层缓存使树高不等于物理 I/O，非聚簇索引还可能回表。修改缓冲页会生成 WAL，回刷持久页前必须先持久相应日志。[7] 多索引、页分裂、整页日志与同页合写决定实际放大，A6 的 16.384 倍只是模型。'),p('<strong>Deck 6 shows two alternatives behind one API, not two stores in series.</strong> B+Tree orders keys in pages, descends for point access and follows leaf order for ranges. Cached upper pages make height differ from physical I/O; a non-clustered index may need a row fetch. Buffer changes generate WAL, whose relevant records must be durable before persistent-page flush.[7] Indexes, splits, full-page logs and coalescing determine actual amplification; A6’s 16.384× is only a model.'))
engine+=bi(p('本例 LSM 选择“WAL 持久 → 引擎装入 memtable → 回成功”，SSTable flush/合并在后台；仅有 WAL 文件不代表已经完成内存应用，也不能过早回收恢复所需日志。[5][13] LSM 结构不强制每笔同步落盘，RocksDB 默认非同步写可幸存进程退出却可能在机器故障丢最近写，需按需求设置 <code>WriteOptions.sync=true</code>等持久策略。[13]'),p('The LSM path here chooses durable WAL → engine installs Memtable → success; SSTable flush and compaction run in the background. WAL existence alone is not completed memory application, and required recovery logs must be retained.[5][13] The structure does not force synchronous writes. RocksDB’s default non-sync writes can survive process failure yet lose recent writes on machine failure; configure a durability policy such as <code>WriteOptions.sync=true</code> when required.[13]'))
engine+=h(3,'先定义放大口径，再算持续预算','Define amplification before budgeting sustained load')
engine+=bi(p('本章 WA=引擎写到存储设备字节/用户字节，含 WAL、flush、合并；NAND 内部放大另算。A12：10 MB/s 输入、100 MB/s 盘写预算，WA=6 得 60 MB/s，WA=12 得 120 MB/s，后者已超预算。还需预算合并读 I/O、临时空间和尾延迟；不能把 WAL 顺序写很快当成持续吞吐证明。不同产品指标可能排除 WAL，比较前对齐分子。'),p('Here WA is engine bytes written to storage per user byte, including WAL, flush and compaction; internal NAND amplification is separate. A12’s 10 MB/s input and 100 MB/s write budget yield 60 MB/s at WA=6 but 120 MB/s at WA=12, already over budget. Compaction reads, temporary space and tail latency also matter. Sequential WAL speed is not sustained-throughput proof; align numerators when product metrics exclude WAL.'))
engine+=bi(p('更多未合并文件/版本会增加读工作与空间压力，输入/输出共存还需临时空间。RocksDB 的 immutable memtable、L0 文件和待合并字节积压能触发减速/停写。[9] 限入流、保留后台资源并测恢复速度；加应用实例不修复合并瓶颈。读需合并版本/墓碑；旧值或能恢复旧值的副本尚在时，墓碑不能只凭年龄删除。'),p('More uncompacted files/versions increase lookup work and space pressure, while simultaneous inputs/outputs need temporary space. RocksDB can slow or stop writes for immutable-memtable, L0-file or pending-compaction backlogs.[9] Bound ingestion, reserve background resources and measure recovery; application replicas do not fix this bottleneck. Reads reconcile versions/tombstones; age alone cannot justify deleting a tombstone while older values or restoring replicas remain.'))
engine+=bi(p('正确且未损坏的 Bloom 对已插入键没有假阴性：no 可跳过该点查文件，maybe 仍要查索引/数据，缓存可能免去物理 I/O；它不返回值，也不能把整段范围判空。[1] B+Tree 与 LSM 都能做点查/范围；事务/复制另看协议。选型压测保留真实键偏斜、索引、压缩和后台任务；论文的负载特化思想不是“每个表都配新系统”。[6]'),p('An intact, correctly built Bloom filter has no false negatives for inserted keys: no skips a point-lookup file; maybe still needs index/data probes, possibly served from cache. It returns no value and cannot declare an entire range empty.[1] Both B+Tree and LSM support point/range access; transactions and replication are separate protocols. Benchmark real skew, indexes, compression and background work. Workload specialization does not demand a new system for every table.[6]'))
out+=sec('引擎：热路径之后，还要支付后台成本','Engines: budget background cost after the hot path',engine)

col=figures[6]+bi(p('<strong>图7把一次分析固定在同一不可变快照和 manifest。</strong>只扫 amount 时，一年 1,261,440,000×8 B=10.09152 GB；加 1 B status 共 11.35296 GB，整行则 1.89216 TB。1,500÷8=187.5 是裸字节比，不是延迟倍数。Dremel2010 的列条带与执行树用于只读嵌套分析；这不等于所有列式产品都不支持更新/事务。[4]'),p('<strong>Deck 7 pins analysis to one immutable snapshot and manifest.</strong> Annual amount bytes are 1,261,440,000×8 B=10.09152 GB; adding one-byte status gives 11.35296 GB versus 1.89216 TB of full rows. The 187.5=1,500÷8 ratio concerns raw bytes, not latency. Dremel2010 uses column stripes and an execution tree for read-only nested-data analysis; this does not imply every columnar product lacks updates or transactions.[4]'))
col+=h(3,'关键实现：完整片段才能得到准确 SUM','Implementation: exact SUM requires complete fragments')
col+=bi(p('下面摘自可运行 Java17 示例。可信 manifest 已证明片段完整、不重叠，并固定 query/snapshot/manifestVersion 与内容 hash；可信叶子按该查询的过滤/算子和准确文件算部分和。协调代码只检查身份、重复冲突和完整性，不能从一个 hash 自行证明叶子算对。空 manifest 表示已验证的空数据集，非请求漏传。'),p('This excerpt compiles in the runnable Java17 example. A trusted manifest proves complete, disjoint fragments and pins query/snapshot/manifestVersion/content hashes. Trusted leaves apply the declared query filter/operator to the exact files. This coordinator checks identity, duplicate conflicts and completeness; a hash alone cannot prove a leaf computed correctly. An empty manifest means a verified empty dataset, not omitted request data.'))
col+=code('ExactSum.java','Java17 · sum','teaching','aggregate')
col+=bi(p('正常 A=100 分、B=200 分得到 300；重投相同 A 仍为 300，错快照、错 manifest 版本、陌生片段或冲突部分和拒绝；缺 B 是 INCOMPLETE，绝不把 100 当准确总计。用 BigInteger 累加避免 long 溢出；仍需上游定义金额单位、符号与范围。真实服务应有截止时间、有界重试缺片、版本化完整 manifest 和验证过的叶子回执。'),p('With A=100 cents and B=200 cents, the sum is 300; replaying identical A still gives 300. Reject wrong snapshots/manifest revisions, unknown fragments and conflicting partial sums. Missing B is INCOMPLETE, never an exact 100. BigInteger avoids long overflow, while upstream still defines units/sign/range. A real service also needs deadlines, bounded missing-fragment retries, immutable complete manifests and verified leaf receipts.'))
col+=bi(p('小数据先用行存 SUM；历史扫描与结账抢 I/O 时再导出列文件，记录截止位置和完整 manifest。导出延迟可被报表接受，不能借给确认页。选型来自读取字段/范围与更新要求，不能只按“宽表也有列”或“列存一定只读”分类。'),p('For small data, start with a row-store SUM. Export column files with a cutoff and complete manifest when history scans contend with checkout I/O. Reports may tolerate export lag; confirmation cannot. Fields/ranges and update requirements drive the choice, rather than equating wide-row columns with stripes or assuming all column stores are read-only.'))
out+=sec('列条带：少数字段，完整快照聚合','Column stripes: a few fields, one complete snapshot',col)

wrap=bi(p('<strong>口述顺序：</strong>访问键/查询 → 原子不变量 → 成功与故障承诺 → 引擎/复制与代价。结账先守住订单、库存、幂等同提交；聊天按会话时间聚集；对象按准确版本发布；搜索从可恢复源派生；分析缺片不回准确总计。规模不足以单独决定产品。'),p('<strong>Interview order:</strong> access/query → atomic invariant → success/failure promise → engine/replication and cost. Checkout joins order/stock/idempotency. Chat clusters conversation/time; objects publish exact versions; search derives from a recoverable source; missing analytical fragments never produce an exact sum. Scale alone does not choose a product.'))
wrap+=table([('错误捷径','Shortcut'),('应补的条件','Missing condition')],[
 [('“SQL 就是 B+Tree，KV 就是 AP”','“SQL means B+Tree; KV means AP”'),('模型、布局、引擎、事务与复制分别查','Inspect model, layout, engine, transactions and replication separately')],
 [('“先读库存再写回就安全”','“Read stock, then write it back”'),('数据库内条件更新，核行数，和订单/回执同事务','Database predicate, row-count check and same-commit order/receipt')],
 [('“W=2 就是两份落盘”','“W=2 means two durable copies”'),('ACK 契约另定；Dynamo 还有缓冲写优化','ACK meaning is separate; Dynamo also describes buffered writes')],
 [('“同步确认就能随便读副本”','“Sync acknowledgment permits any replica read”'),('等指定副本回放并用新视图，或回当前主库','Wait for the chosen replica to replay and use a fresh view, or read current primary')],
 [('“页写 7.86 MB/s 是磁盘上界”','“7.86 MB/s bounds disk writes”'),('只算三页教学模型，WAL/其他写和后台任务另计','Only the three-page model; add WAL, other writes and background work')],
 [('“超时就换键/直接清扫”','“Timeout means new key or immediate cleanup”'),('先恢复原结果；清扫须赢状态 CAS 并复查迟到体','Recover the original result; cleanup needs a CAS win and late-body rechecks')]])
wrap+=bi(p('本页三段代码与 <a href="../examples/ch37/README.md">examples/ch37</a> 同源。SQLite 多连接/进程退出验证结账与 CAS；Java17 验证聚合契约。单写者适配不证明多主、PostgreSQL 行锁、真实对象版本核验、复制切主、断电或生产容量。分片前先测不变量/工作集/尾延迟；跨片库存可选支持的分布式事务或业务预留/补偿，不能由“拆库”凭空获得原子性。外部一致的一个实现是 Spanner 的 TrueTime 排序与提交等待。[3]'),p('The three snippets match <a href="../examples/ch37/README.md">examples/ch37</a>. SQLite connections/process exit exercise checkout/CAS; Java17 checks aggregation contracts. This single-writer adapter does not prove multi-primary behavior, PostgreSQL row locks, live object verification, replication failover, power-loss safety or production capacity. Measure invariants, working set and tail latency before sharding. Cross-shard stock needs a supported distributed transaction or business reservation/compensation. Spanner’s TrueTime ordering and commit wait provide one implementation of external consistency.[3]'))
out+=sec('面试复盘与验证边界','Interview recap and validation boundaries',wrap)

refs=re.search(r'<ol class="references">[\s\S]*?</ol>',old).group(0)
refs=refs.replace('https://static.googleusercontent.com/media/research.google.com/en//archive/bigtable-osdi06.pdf','https://storage.googleapis.com/gweb-research2023-media/pubtools/4443.pdf').replace('accessed 2026-10-07','checked 2026-10-24')
refs=refs.replace('sloppy quorum and hinted handoff.','sloppy quorum and hinted handoff; §6.1 buffered writes trade durability for latency.')
refs=refs.replace('If-None-Match for create-only object writes, not cross-store transactions.</span>','If-None-Match for create-only object writes, not cross-store transactions.</span> <a href="https://docs.aws.amazon.com/AmazonS3/latest/userguide/checking-object-integrity-upload.html">Object integrity and ETags</a>.')
refs=refs.replace('</ol>','''<li id="ref-isolation">[11] PostgreSQL18, <a href="https://www.postgresql.org/docs/18/transaction-iso.html">Transaction Isolation</a>. <span class="lang-zh">Read Committed 条件更新等待后重验 WHERE；查询/事务快照区别。</span><span class="lang-en">Read Committed rechecks UPDATE predicates after waiting; query and transaction snapshots differ.</span></li>
<li id="ref-sqlite">[12] SQLite, <a href="https://sqlite.org/lang_transaction.html">Transactions</a>, <a href="https://sqlite.org/lang_returning.html">RETURNING</a>, <a href="https://sqlite.org/releaselog/3_38_0.html">3.38.0 release / unixepoch</a>, checked 2026-10-24. <span class="lang-zh">BEGIN IMMEDIATE 单写者、旧快照；RETURNING 不等于提交；unixepoch 需3.38+。</span><span class="lang-en">BEGIN IMMEDIATE and one writer, retained snapshots, RETURNING before commit, unixepoch requires3.38+.</span></li>
<li id="ref-rocks-sync">[13] RocksDB, <a href="https://github.com/facebook/rocksdb/wiki/Basic-Operations">Basic Operations / Synchronous Writes</a>, <a href="https://github.com/facebook/rocksdb/wiki/Write-Ahead-Log-(WAL)">WAL</a>, checked 2026-10-24. <span class="lang-zh">sync 默认与进程/机器故障边界；WAL 回收须相关列族刷表越过序号。</span><span class="lang-en">Sync defaults and process/machine-failure boundary; retain WAL until relevant families flush beyond its sequence.</span></li>
<li id="ref-multi-index">[14] PostgreSQL18, <a href="https://www.postgresql.org/docs/18/indexes-multicolumn.html">Multicolumn Indexes</a>. <span class="lang-zh">B-tree 前导等值与后续范围约束缩小扫描区间。</span><span class="lang-en">Leading equality followed by range bounds limits a B-tree scan.</span></li></ol>''')
out+=sec('引用与延伸阅读','References and further reading',refs+p(lang('站内延伸：','On this site:')+' <a href="ch06.html">Ch06 · KV</a> · <a href="ch13.html">Ch13 · Search</a> · <a href="ch22.html">Ch22 · Objects</a> · <a href="ch36.html">Ch36 · CAP/PACELC</a> · <a href="ch38.html">Ch38 · Cache</a>'))
flash=old[old.index('  <section>\n    <h2><span class="lang-zh">闪卡'):old.rfind('  </section>')+len('  </section>')]
flash=flash.replace('订单、明细、库存条件和唯一幂等结果同提交，查询规模还需实测。','订单、明细、库存条件和唯一幂等结果同提交；不足整笔撤销，拒绝回执也持久。').replace('Order, lines, stock predicates and the unique idempotency result commit together; capacity still needs testing.','Order, lines, stock predicates and unique receipt commit together; undo all effects on shortage and persist the refusal.')
flash=flash.replace('不等于；WAL 落盘与回放可见分开，确认读要应用屏障或当前主库。','不等于；WAL 落盘与回放可见分开，确认读要应用屏障/当前主库，并结束旧快照。').replace('No. WAL durability and replay visibility differ; confirmation needs an apply barrier or current-primary read.','No. WAL durability and replay visibility differ; use an apply barrier/current primary and leave old snapshots.')
flash=flash.replace('W={N1,N4} 已确认，N2 恢复但提示和 N3 写未到，R={N2,N3} 可都读旧。','W={N1,N4}，N2 恢复但提示/N3 写未到，R={N2,N3} 可都旧；W 数不定义落盘。').replace('W={N1,N4} succeeds; after N2 recovers but before handoff/N3 delivery, R={N2,N3} may return two old values.','W={N1,N4}; after N2 recovers but before handoff/N3 delivery, R={N2,N3} may read old. W does not define durability.')
flash=flash.replace('1,500 B÷8 B 的裸字节比，不是提速承诺；缺片时不能返回准确 SUM。','1,500 B÷8 B 的裸字节比，不是提速承诺；固定 manifest，去重且齐片才回准确 SUM。').replace('The raw-byte ratio 1,500 B÷8 B, not a speed promise; missing fragments cannot yield an exact SUM.','The raw-byte ratio 1,500 B÷8 B, not a speed promise; pin the manifest, dedupe and require all fragments for exact SUM.')
out+=flash+'\n'+old[old.rfind('  </section>')+len('  </section>'):]
